from typing import List

class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        # copy[i] must equal original[i] + c for some constant integer c.
        # Count integer values of c satisfying all bounds.
        low = -10**30
        high = 10**30

        for val, (u, v) in zip(original, bounds):
            low = max(low, u - val)
            high = min(high, v - val)
            if low > high:
                return 0

        return max(0, high - low + 1)
```

