from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(baskets)

        size = 1
        while size < n:
            size <<= 1

        tree = [-1] * (2 * size)
        tree[size:size + n] = baskets

        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[i << 1], tree[i << 1 | 1])

        def find_leftmost(need: int) -> int:
            if tree[1] < need:
                return -1

            node = 1
            while node < size:
                left = node << 1
                if tree[left] >= need:
                    node = left
                else:
                    node = left | 1

            idx = node - size
            return idx if idx < n else -1

        def remove(idx: int) -> None:
            pos = idx + size
            tree[pos] = -1
            pos >>= 1

            while pos:
                tree[pos] = max(tree[pos << 1], tree[pos << 1 | 1])
                pos >>= 1

        unplaced = 0

        for fruit in fruits:
            basket_idx = find_leftmost(fruit)
            if basket_idx == -1:
                unplaced += 1
            else:
                remove(basket_idx)

        return unplaced
