from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        if not groups:
            return []
        if not elements:
            return [-1] * len(groups)

        max_group = max(groups)
        sentinel = len(elements)

        # first_index[x] = smallest index of an element with value x,
        # ignoring values that cannot divide any group.
        first_index = [sentinel] * (max_group + 1)
        for idx, value in enumerate(elements):
            if value <= max_group and idx < first_index[value]:
                first_index[value] = idx

        # best[g] = smallest element index that divides g.
        best = [-1] * (max_group + 1)

        for value in range(1, max_group + 1):
            idx = first_index[value]
            if idx == sentinel:
                continue

            for multiple in range(value, max_group + 1, value):
                current = best[multiple]
                if current == -1 or idx < current:
                    best[multiple] = idx

        return [best[group] for group in groups]
