class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        counts = [0] * 51
        for num in nums:
            counts[num] += 1

        total_k = counts[k]

        # If there are no k's initially, we can convert all occurrences of
        # the most frequent other value into k by choosing the whole array.
        if total_k == 0:
            return max(counts)

        best_gain = 0

        # Choose value v = k - x inside the updated subarray.
        # Gain = count of v in subarray - count of k in subarray.
        for value in range(1, 51):
            if value == k or counts[value] <= best_gain:
                continue

            current = 0
            for num in nums:
                if num == value:
                    current += 1
                elif num == k:
                    current -= 1

                if current < 0:
                    current = 0
                elif current > best_gain:
                    best_gain = current

        return total_k + best_gain
