                r, c = i, j

    path = [min_val]
    if k == 1:
        return path

    for _ in range(1, k):
        best_val = None
        best_r = best_c = None

        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m:
                val = grid[nr][nc]
                if best_val is None or val < best_val:
                    best_val = val
                    best_r, best_c = nr, nc

        if best_val is None:
            path.extend([path[-1]] * (k - len(path)))
