from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        offline_until = [-1] * numberOfUsers

        events_by_time = {}
        for idx, event in enumerate(events):
            timestamp = int(event[1])
            events_by_time.setdefault(timestamp, []).append((idx, event))

        for timestamp in sorted(events_by_time):
            # Automatic come-backs happen before any message at this timestamp.
            for user_id in range(numberOfUsers):
                if offline_until[user_id] <= timestamp:
                    offline_until[user_id] = -1

            current_events = sorted(events_by_time[timestamp])

            # Process all offline status changes before messages at this timestamp.
            for _, event in current_events:
                if event[0] == "OFFLINE":
                    user_id = int(event[2])
                    offline_until[user_id] = timestamp + 60

            # Process message events.
            for _, event in current_events:
                if event[0] != "MESSAGE":
                    continue

                for token in event[2].split():
                    if token == "ALL":
                        for user_id in range(numberOfUsers):
                            mentions[user_id] += 1
                    elif token == "HERE":
                        for user_id in range(numberOfUsers):
                            if offline_until[user_id] <= timestamp:
                                mentions[user_id] += 1
                    else:
                        user_id = int(token[2:])
                        mentions[user_id] += 1

        return mentions
